    function confirmRedirect() {
        // 弹出确认对话框
        const userConfirmed = confirm("您确定要跳转到首页吗？");

        // 根据用户选择执行操作
        if (userConfirmed) {
            // 用户点击"确定" - 执行跳转
            window.location.href = "https://xzhnew.github.io";
        } else {
            // 用户点击"取消" - 留在当前页面
            console.log("用户取消跳转");
        }
    }
